function getThemeList() {
	return THEME_ORDER.map(id => {
		const theme = THEMES[id]
		return {
			id: theme.id,
			name: theme.name,
			description: theme.description,
			category: theme.category,
			primaryColor: theme.light.primaryColor
		}
	})
}

function getThemesByCategory() {
	const result = {}
	for (const [categoryId, category] of Object.entries(THEME_CATEGORIES)) {
		result[categoryId] = {
			name: category.name,
			themes: category.themes.map(id => {
				const theme = THEMES[id]
				return {
					id: theme.id,
					name: theme.name,
					description: theme.description,
					primaryColor: theme.light.primaryColor
				}
			})
		}
	}
	return result
}

function getThemeById(themeId) {
	return THEMES[themeId] || THEMES['default-blue']
}

function getDefaultTheme() {
	return THEMES['default-blue']
}

export default {
	THEMES,
	THEME_ORDER,
	THEME_CATEGORIES,
	getThemeList,
	getThemesByCategory,
	getThemeById,
	getDefaultTheme
}
